import{_ as t,o as s,c as i,ao as r}from"./chunks/framework.Cvh8ZM6D.js";const g=JSON.parse('{"title":"Import","description":"","frontmatter":{"permalink":"/docs/getting-started/import/"},"headers":[],"relativePath":"docs/getting-started/import.md","filePath":"docs/getting-started/import.md"}'),a={name:"docs/getting-started/import.md"};function o(n,e,d,l,h,c){return s(),i("div",null,[...e[0]||(e[0]=[r(`<h1 id="import" tabindex="-1">Import <a class="header-anchor" href="#import" aria-label="Permalink to “Import”">​</a></h1><p>After initial setup, publicly available content (e.g., service offerings) can be imported into your instance of the Service Lifecycle Management.</p><h2 id="service-registry" tabindex="-1">Service Registry <a class="header-anchor" href="#service-registry" aria-label="Permalink to “Service Registry”">​</a></h2><p>To import content into the Service Registry of the Service Lifecycle Management local directories or git repositories can be used. See the two sections below for more information how to configure import from local directories or git repositories. The import can be started using this command:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker-compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> up</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --force-recreate</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> service-registry-init</span></span></code></pre></div><h3 id="local-directories" tabindex="-1">Local Directories <a class="header-anchor" href="#local-directories" aria-label="Permalink to “Local Directories”">​</a></h3><p>Update in the <code>.env</code> file in the <code>compose</code> directory the variable <code>SERVICE_REGISTRY_INITIALIZATION_LOCAL_DIRECTORIES</code> with your directories. Multiple directories must be seperated by comma. The defined directories must be added as volumes to the <code>service-registry-init</code> service in the <code>docker-compose.yml</code>.</p><p>Example of <code>.env</code>:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">SERVICE_REGISTRY_INITIALIZATION_LOCAL_DIRECTORIES</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/my/local/dir1,/my/local/dir2</span></span></code></pre></div><p>Example of <code>docker-compose.yml</code>:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">...</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  service-registry-init</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    ...</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    volumes</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    ...</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;/my/local/dir1:/my/local/dir1&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;/my/local/dir2:/my/local/dir2&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">...</span></span></code></pre></div><h3 id="git-repositories" tabindex="-1">Git Repositories <a class="header-anchor" href="#git-repositories" aria-label="Permalink to “Git Repositories”">​</a></h3><p>Update in the <code>.env</code> file in the <code>compose</code> directory the variable <code>SERVICE_REGISTRY_INITIALIZATION_GIT_REPOS</code> with your git repositories. Default value is the public <a href="https://github.com/FabOS-AI/fabos-slm-service-registry-content" target="_blank" rel="noreferrer">service registry content repository</a>. Multiple git repositories must be seperated by comma. Authentication for a git repository can be defined in the form <code>{Username}:{PasswordOrAccessToken}@{RepoUrl}</code>.</p><p>Example:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">SERVICE_REGISTRY_INITIALIZATION_GIT_REPOS</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">https://github.com/FabOS-AI/fabos-slm-service-registry-content.git,myGitUser:myGitUserPassword@https://my-private-git-repo.git</span></span></code></pre></div><h2 id="resource-registry" tabindex="-1">Resource Registry <a class="header-anchor" href="#resource-registry" aria-label="Permalink to “Resource Registry”">​</a></h2><p>To populate the Resource Registry of the Service Lifecycle Management with an already available list of known, a simple utility tool can be used to speed up the process. The tool can be found on <a href="https://github.com/FabOS-AI/fabos-slm-resource-registry-init" target="_blank" rel="noreferrer">GitHub</a>. In the current version, the tool parses a given <strong>Excel file</strong> and populates the Resource Registry with the contained resources.</p><div class="warning custom-block"><p class="custom-block-title">ATTENTION</p><p>The tool was initially only intended for a quick repopulation of the Resource Registry in demo setups. Consequently, the tool is rudimentary in design and will be changed in the future in order to be more aligned with the SLM base setup and components.</p></div><p>Since the tool interacts with the REST-API of the <code>Resource Registry</code>, to use the tool just clone the repo into any directory:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/FabOS-AI/fabos-slm-resource-registry-init</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> fabos-slm-resource-registry-init</span></span></code></pre></div><p>Now the Excel file <code>example.xlsx</code> needs to be adapted to the list of resources to be added to the Resource Registry. There are two example devices listed to familiarize with the pattern. The following fields are definitely required to be filled (per device):</p><table tabindex="0"><thead><tr><th><strong>variable</strong></th><th><strong>type</strong></th><th><strong>description</strong></th></tr></thead><tbody><tr><td>Device</td><td>string</td><td>An arbitrary device name, for easier reference</td></tr><tr><td>user</td><td>string</td><td>The user name of the resource, in order to be accessed</td></tr><tr><td>password</td><td>string</td><td>The password of the corresponding user</td></tr><tr><td>hostname</td><td>string</td><td>The hostname of the resource</td></tr><tr><td>eth0 IP</td><td>string</td><td>The IP of the resource. Additionally, eth1 IP can be filled as well, but eth0 will be prefered</td></tr><tr><td>is_resource</td><td>string</td><td>A flag that determines if device is added to the resource registry. Set it to &quot;yes&quot; in order to be added</td></tr><tr><td>UUID</td><td>string</td><td>The UUID of the resource, can be generated externally</td></tr></tbody></table><p>Additionally, following flags can be used to trigger the install of an capability for the resource (optional):</p><table tabindex="0"><thead><tr><th><strong>variable</strong></th><th><strong>type</strong></th><th><strong>description</strong></th></tr></thead><tbody><tr><td>DC_Docker</td><td>string</td><td>If set to &quot;yes&quot;, Docker capability will be added to resource</td></tr><tr><td>DC_Swarm</td><td>string</td><td>If set to &quot;yes&quot;, Swarm capability will be added to resource</td></tr><tr><td>DC_K3s</td><td>string</td><td>If set to &quot;yes&quot;, K3s capability will be added to resource</td></tr></tbody></table><p>In a second step, the settings for the tool need to be adapted and verified. Therefore open the <code>docker-compose.yaml</code> in a text editor and change the variables in the <code>environment</code>-section accoding to your local environment. When the Service Lifecycle Management was setup through the inital setup, all variables should already be matching the local environment. See the following table for details on the settings:</p><table tabindex="0"><thead><tr><th><strong>variable</strong></th><th><strong>type</strong> <div style="width:110px;"></div></th><th><strong>default</strong></th><th><strong>description</strong> <div style="width:500px;"></div></th></tr></thead><tbody><tr><td>SLM_HOST</td><td>string</td><td>&quot;<a href="http://172.17.0.1" target="_blank" rel="noreferrer">http://172.17.0.1</a>&quot;</td><td>The full qualified domain name of the SLM host or IP address, including the http prefix</td></tr><tr><td>SLM_USER</td><td>string</td><td>&quot;fabos&quot;</td><td>The user to be used to add the resources to the SLM</td></tr><tr><td>SLM_PASSWORD</td><td>string</td><td>&quot;password&quot;</td><td>The corresponding password for the SLM user</td></tr><tr><td>XLSX_FILE</td><td>string</td><td>&quot;/files/example.xlsx&quot;</td><td>The Excel file inside the container. On default all file of the cloned directory are mounted under &quot;/files&quot;</td></tr><tr><td>SHEET_NAME</td><td>string</td><td>&quot;DEVICES&quot;</td><td>The sheet name inside the Excel file which contains the list of resources</td></tr><tr><td>FORCE_OVERWRITE</td><td>bool (as string)</td><td>&quot;False&quot;</td><td>Determines if resources and their capabilites should be overwritten if they already exist</td></tr><tr><td>FORCE_DELETE</td><td>bool (as string)</td><td>&quot;False&quot;</td><td>Determines if a resources listed in the EXCEL sheet should be deleted in the first step</td></tr><tr><td>DELETE_ALL</td><td>bool (as string)</td><td>&quot;False&quot;</td><td>Determines if all resources (not only listed resources in the EXCEL) should be deleted in the first step, to start with a clean resource registry</td></tr><tr><td>PING_CHECK</td><td>bool (as string)</td><td>&quot;False&quot;</td><td>Determines if resources should be pinged before added to the resource registry</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">ATTENTION</p><p>Especially in a setup with docker be aware of the correct host used in the <code>SLM_HOST</code> variable. In Docker <strong>localhost</strong> and <strong>127.0.0.1</strong> will not work, instead try the magic internal Docker host <strong>host.docker.internal</strong>, <strong>172.17.0.1</strong> or in best case the regular IP of the host.</p></div><p>Finally, the tool can be run through Docker. Therefore use Docker-Compose to build and run the tool:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker-compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> up</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --build</span></span></code></pre></div><p>A successful run of the tool will print a summary at the end of the run. For the given resource in the <code>example.xlsx</code> file, the summary looks like this:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>resource-registry-init  | SUMMARY -------------------------------------------------------------------------------------------------------------------</span></span>
<span class="line"><span>resource-registry-init  | Resources deleted (via REST): []</span></span>
<span class="line"><span>resource-registry-init  | Resources accessible (via ping): []</span></span>
<span class="line"><span>resource-registry-init  | Resources added to registry (via REST): [</span></span>
<span class="line"><span>resource-registry-init  |   &quot;0226a355-3156-43e8-b51e-3b670c6ba7c3, SOCP2001-20011111, 192.168.153.48&quot;,</span></span>
<span class="line"><span>resource-registry-init  |   &quot;7fd248f5-e698-46f1-b30e-1ac568d66c15, RevPi30562, 192.168.153.51&quot;</span></span>
<span class="line"><span>resource-registry-init  | ]</span></span>
<span class="line"><span>resource-registry-init  | Capabilities added to resources (via REST): [</span></span>
<span class="line"><span>resource-registry-init  |   &quot;7fd248f5-e698-46f1-b30e-1ac568d66c15, RevPi30562, [&#39;DOCKER&#39;]&quot;</span></span>
<span class="line"><span>resource-registry-init  | ]</span></span>
<span class="line"><span>resource-registry-init  | Resource Registry Setup Done!</span></span>
<span class="line"><span>resource-registry-init  | Took: 24.11s</span></span></code></pre></div><p>This indicates that the two listed resources (<code>SOCP2001-20011111</code>, <code>RevPi30562</code>) were successfully added to the Resource Registry and that the <code>Docker</code> capability was also added for the <code>RevPi</code> device.</p>`,32)])])}const u=t(a,[["render",o]]);export{g as __pageData,u as default};
